import{_ as a,o as r,c as i,ag as t}from"./chunks/framework.DB9Ll7VW.js";const g=JSON.parse('{"title":"Changelog","description":"Recent Sikshya LMS (free) and Sikshya Pro releases — what changed, what to test, and the safe upgrade path.","frontmatter":{"title":"Changelog","description":"Recent Sikshya LMS (free) and Sikshya Pro releases — what changed, what to test, and the safe upgrade path."},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1778327862000}'),o={name:"changelog.md"};function n(s,e,l,d,c,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>This page tracks user-relevant changes for <strong>Sikshya</strong> (free) and <strong>Sikshya Pro</strong>. Plugin metadata in <code>readme.txt</code> is the canonical source; this page mirrors the highlights in a single place.</p><h2 id="sikshya-free" tabindex="-1">Sikshya (free) <a class="header-anchor" href="#sikshya-free" aria-label="Permalink to &quot;Sikshya (free)&quot;">​</a></h2><h3 id="_1-0-3-—-2026-05-08" tabindex="-1">1.0.3 — 2026-05-08 <a class="header-anchor" href="#_1-0-3-—-2026-05-08" aria-label="Permalink to &quot;1.0.3 — 2026-05-08&quot;">​</a></h3><ul><li><strong>Readme refresh</strong> for the WordPress.org plugin directory: SEO-oriented short description and tags; quick links (Mantrabrain documentation, demo, pricing, community); structured sections (At a glance, self-hosted LMS, FAQs including block editor and optional usage insights); third-party services and privacy disclosure aligned with docs.</li><li><strong>Plugin listing title</strong> aligned with WordPress plugin directory expectations.</li><li><strong>Screenshot captions</strong> tuned for LMS and checkout keywords.</li><li><strong>Installation and security reporting</strong> guidance clarified.</li><li><strong>Plugin metadata:</strong> version bump; default documentation URLs in Plugin API / admin bootstrap now point to <code>https://docs.mantrabrain.com/sikshya-wordpress-plugin/</code>.</li></ul><p><strong>Upgrade notice:</strong> Documentation and WordPress.org readme update — improved plugin directory copy, Mantrabrain documentation links, expanded FAQ, and privacy / third-party transparency. No breaking runtime changes expected; clear any full-page caches after update if your host caches plugin metadata.</p><h3 id="_1-0-2-—-2026-05-04" tabindex="-1">1.0.2 — 2026-05-04 <a class="header-anchor" href="#_1-0-2-—-2026-05-04" aria-label="Permalink to &quot;1.0.2 — 2026-05-04&quot;">​</a></h3><ul><li><strong>Admin (React shell):</strong> Grading &amp; submissions and gradebook screens — toolbar layout fixes so Course, Search, and Status filters align cleanly; contextual helper copy moved below the filter row; clearer sidebar icons for Gradebook and related entries.</li><li><strong>Marketing:</strong> Pro upgrade notice now uses &quot;up to 50% off&quot; instead of &quot;50%+ OFF&quot; for clearer, defensible wording (classic admin notice + in-app strip).</li><li><strong>Public:</strong> course category index and taxonomy routing improvements for a better category archive experience.</li><li><strong>Build:</strong> refreshed compiled admin JavaScript / CSS from current sources.</li></ul><p><strong>Upgrade notice:</strong> Maintenance and UX release — admin grading and gradebook toolbar layout, clearer Pro upgrade wording, course category archives, and refreshed admin assets. Safe to apply over 1.0.0.x; clear page caches if your host caches admin or theme assets.</p><h3 id="_1-0-0-1-—-2026-05-02" tabindex="-1">1.0.0.1 — 2026-05-02 <a class="header-anchor" href="#_1-0-0-1-—-2026-05-02" aria-label="Permalink to &quot;1.0.0.1 — 2026-05-02&quot;">​</a></h3><ul><li><strong>Certificate:</strong> fixes for issues in the admin certificate designer (layout, editing, and related flows).</li><li><strong>Build:</strong> refreshed compiled admin React assets from the latest sources.</li></ul><p><strong>Upgrade notice:</strong> Maintenance release — certificate builder fixes and updated admin build assets. Safe to apply on top of 1.0.0; clear any full-page caches if your host caches admin scripts.</p><h3 id="_1-0-0-—-2026-04-30" tabindex="-1">1.0.0 — 2026-04-30 <a class="header-anchor" href="#_1-0-0-—-2026-04-30" aria-label="Permalink to &quot;1.0.0 — 2026-04-30&quot;">​</a></h3><ul><li><strong>Initial public release.</strong></li><li>Core course, lesson, quiz, and question model with builder-oriented admin UI.</li><li>Student and instructor roles with capability-safe management surfaces.</li><li>Baseline commerce: Stripe / PayPal-oriented checkout, coupons, orders.</li><li>Learner templates, account views, and progress-oriented flows.</li><li>REST-aligned services where documented for integrations.</li><li>Default certificate presets (Regalia &amp; Vertex) ship without QR blocks; QR-style verification remains documented as a Pro-oriented enhancement.</li><li>Requires PHP 7.4+ and WordPress 6.0+; tested on current stable WordPress releases.</li><li><strong>Checkout (with Sikshya Pro Dynamic Checkout Fields):</strong> optional server-rendered dynamic field markup — JavaScript attaches listeners and visibility without rebuilding the form in the browser; includes <code>CheckoutDynamicFieldsView</code> and refactored checkout helpers (<code>dfBindDynamicFields</code>, <code>dfSyncValuesFromHost</code>).</li></ul><p><strong>Upgrade notice:</strong> First stable release. Back up your site before production rollout; confirm permalinks, required pages, and payment keys after activation. Clear page caches if checkout forms are cached at the edge.</p><h2 id="sikshya-pro" tabindex="-1">Sikshya Pro <a class="header-anchor" href="#sikshya-pro" aria-label="Permalink to &quot;Sikshya Pro&quot;">​</a></h2><h3 id="_1-0-0-—-2026-04-30-1" tabindex="-1">1.0.0 — 2026-04-30 <a class="header-anchor" href="#_1-0-0-—-2026-04-30-1" aria-label="Permalink to &quot;1.0.0 — 2026-04-30&quot;">​</a></h3><ul><li><strong>Initial commercial release:</strong> licensing, Pro add-ons, premium gateways, and automation built on the free Sikshya LMS core.</li><li><strong>Dynamic Checkout Fields:</strong> renders checkout dynamic field HTML in PHP using the free plugin&#39;s <code>Sikshya\\Frontend\\Site\\CheckoutDynamicFieldsView</code> (use Sikshya LMS <strong>1.0.0</strong> with that class and the matching <code>checkout-page.js</code>). The checkout script binds events, syncs values, and applies conditional visibility instead of replacing server-rendered markup.</li></ul><p><strong>Upgrade notice:</strong> First release of Sikshya Pro for sites already running Sikshya LMS. Install Composer production dependencies before activation; keep Sikshya LMS updated alongside Pro.</p><h2 id="upgrade-strategy" tabindex="-1">Upgrade strategy <a class="header-anchor" href="#upgrade-strategy" aria-label="Permalink to &quot;Upgrade strategy&quot;">​</a></h2><h3 id="always" tabindex="-1">Always <a class="header-anchor" href="#always" aria-label="Permalink to &quot;Always&quot;">​</a></h3><ol><li><strong>Back up</strong> your site (database + plugins folder) before any major update.</li><li><strong>Update on staging</strong> first when possible.</li><li><strong>Update Sikshya before Sikshya Pro</strong> — Pro may depend on classes / methods introduced in a free release.</li><li><strong>Visit the admin</strong> after update so any one-time migrations run via <code>Installer::activate()</code>.</li></ol><h3 id="when-updating-pro" tabindex="-1">When updating Pro <a class="header-anchor" href="#when-updating-pro" aria-label="Permalink to &quot;When updating Pro&quot;">​</a></h3><ul><li>Read the Pro changelog for that release.</li><li>Confirm your free plugin is at or above the version Pro requires.</li><li>Run <code>composer install --no-dev --optimize-autoloader</code> if you cloned the source (distributed ZIPs are pre-built).</li><li>Re-check <strong>Sikshya → License → Re-check license</strong> after the update.</li></ul><h3 id="when-updating-free" tabindex="-1">When updating Free <a class="header-anchor" href="#when-updating-free" aria-label="Permalink to &quot;When updating Free&quot;">​</a></h3><ul><li>Read the free changelog.</li><li>Update Pro in the same window if a coupled change is mentioned.</li><li>Visit a public course page and the learner account page in a private window — these are the highest-traffic flows.</li></ul><h2 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h2><p>Sikshya follows a <code>MAJOR.MINOR.PATCH</code> scheme:</p><ul><li><strong>MAJOR</strong> — breaking changes (rare; expect a migration guide in this changelog).</li><li><strong>MINOR</strong> — new features, additions, deprecations.</li><li><strong>PATCH</strong> — bug fixes, security, documentation.</li></ul><p>Pro tracks free&#39;s <code>MAJOR</code> baseline closely but ships its own <code>MINOR</code> / <code>PATCH</code> cadence for add-ons.</p><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><p>The current roadmap is published on the <a href="https://mantrabrain.com/plugins/sikshya-lms/" target="_blank" rel="noreferrer">Mantrabrain product page</a> and changelog notes mirror the public-facing items. Priority items for upcoming releases:</p><ul><li><strong>Free:</strong> mobile-first lesson player polish, better course archive filters, additional default certificate presets.</li><li><strong>Pro:</strong> additional CRM / ESP integrations, deeper Zapier triggers, improved live class workflows, expanded marketplace tools.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/installation">Installation</a> — confirm your version after update.</li><li><a href="/docs/troubleshooting">Troubleshooting</a> — common post-update issues.</li><li><a href="/docs/support">Support</a> — get help with a problematic update.</li></ul>',35)])])}const p=a(o,[["render",n]]);export{g as __pageData,p as default};
